import{_ as t,o as n,c as s,ah as a}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Demandes de congé","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/conges.md","filePath":"src/guide/conges.md"}'),r={name:"guide/conges.md"};function d(o,e,i,l,u,c){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="demandes-de-conge" tabindex="-1">Demandes de congé <a class="header-anchor" href="#demandes-de-conge" aria-label="Permalink to &quot;Demandes de congé&quot;">​</a></h1><p>Les congés sont l&#39;une des rares fonctions d&#39;ERA qui ne dépendent pas de votre rôle : <strong>tout membre du personnel</strong> dépose ses propres demandes, qu&#39;il soit enseignant, caissier, infirmier ou responsable d&#39;internat. La décision suit la même règle que les autres demandes : la direction du site de la personne, la direction générale ou l&#39;administration.</p><h2 id="deposer-une-demande" tabindex="-1">Déposer une demande <a class="header-anchor" href="#deposer-une-demande" aria-label="Permalink to &quot;Déposer une demande&quot;">​</a></h2><p>Depuis <strong>Mes demandes de congé</strong> :</p><ol><li>Renseignez le <strong>type</strong> : congé payé, congé sans solde ou congé maladie.</li><li>Indiquez la <strong>date de début</strong> et la <strong>date de fin</strong>.</li><li>Écrivez le <strong>motif</strong>.</li><li>Cliquez sur <strong>Soumettre la demande</strong>.</li></ol><p>La demande part au statut <strong>En attente</strong>. Vous n&#39;avez rien d&#39;autre à faire : la direction de votre site, la direction générale et l&#39;administration en sont prévenues, et la voient dans leur page <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a>.</p><p>Quand votre demande est décidée, vous recevez une notification : congé accordé, ou refusé avec le motif.</p><h2 id="suivre-ses-demandes" tabindex="-1">Suivre ses demandes <a class="header-anchor" href="#suivre-ses-demandes" aria-label="Permalink to &quot;Suivre ses demandes&quot;">​</a></h2><p>La section <strong>Historique</strong> de la même page liste vos demandes passées et en cours, avec leur statut :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Ce qu&#39;il signifie</th></tr></thead><tbody><tr><td>En attente</td><td>Déposée, pas encore examinée</td></tr><tr><td>Approuvée</td><td>Accordée par l&#39;administration</td></tr><tr><td>Rejetée</td><td>Refusée — le motif du rejet est affiché avec la demande</td></tr></tbody></table><p>Vous ne voyez que vos propres demandes, jamais celles de vos collègues.</p><div class="tip custom-block"><p class="custom-block-title">Le dépôt n&#39;est pas ouvert à tout le monde</p><p>Cette page suppose que vous ayez une fiche de personnel dans l&#39;établissement. Un compte sans fiche (un parent, un élève) n&#39;y a pas accès — voir <a href="/era-guide/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a> pour la création des fiches.</p></div><h2 id="statuer-sur-les-demandes-direction-et-administration" tabindex="-1">Statuer sur les demandes (direction et administration) <a class="header-anchor" href="#statuer-sur-les-demandes-direction-et-administration" aria-label="Permalink to &quot;Statuer sur les demandes (direction et administration)&quot;">​</a></h2><p>La direction et l&#39;administration disposent d&#39;une vue supplémentaire, <strong>Personnel → Demandes de congé</strong>. Une direction de site y voit les demandes du personnel de ses sites ; la direction générale et l&#39;administrateur, celles de <strong>tout</strong> le personnel. Les demandes en attente se décident aussi depuis la page <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a>, et s&#39;affichent dans les tâches du tableau de bord. Personne ne décide de sa propre demande.</p><p>Pour chaque demande :</p><ul><li><strong>Approuver</strong> l&#39;accorde immédiatement.</li><li><strong>Rejeter</strong> ouvre une fenêtre de confirmation demandant un <strong>motif du rejet</strong>. Ce motif est envoyé à la personne concernée avec la décision, et reste visible dans son propre historique — c&#39;est ce qui lui évite de venir demander pourquoi.</li></ul><p>Une demande déjà traitée reste dans la liste avec sa décision : l&#39;historique sert de trace, rien n&#39;est effacé.</p>',17)])])}const g=t(r,[["render",d]]);export{m as __pageData,g as default};
